// Krag wewnetrzny (Use Case) - definiuje TYLKO to, czego potrzebuje, jako interfejs
interface PaymentGateway {
    boolean charge(double amount);
}

class CheckoutUseCase {
    private final PaymentGateway paymentGateway; // zna TYLKO interfejs
    CheckoutUseCase(PaymentGateway paymentGateway) { this.paymentGateway = paymentGateway; }

    boolean checkout(double amount) {
        return paymentGateway.charge(amount); // logika biznesowa nie wie, KTO to obsluzy
    }
}

// Krag zewnetrzny (adapter) - IMPORTUJE interfejs z wewnatrz, implementuje go
class StripeLikePaymentAdapter implements PaymentGateway {
    public boolean charge(double amount) {
        System.out.println("Obciazam karte przez zewnetrzny system platnosci: " + amount);
        return true; // w realnym kodzie: wywolanie zewnetrznego API platnosci
    }
}

// Montaz w 1 miejscu (np. w main albo konfiguracji frameworka):
CheckoutUseCase useCase = new CheckoutUseCase(new StripeLikePaymentAdapter());

